import{ct as e,n as t,st as n,wt as r}from"./chunks/framework.eUj94whv.js";var i=JSON.parse(`{"title":"design.md","description":"","frontmatter":{},"headers":[],"relativePath":"ai/design-md.md","filePath":"ai/design-md.md","lastUpdated":1791958925000}`),a={name:`ai/design-md.md`};function o(t,i,a,o,s,c){return r(),n(`div`,null,[...i[0]||=[e(`<h1 id="design-md" tabindex="-1">design.md <a class="header-anchor" href="#design-md" aria-label="Permalink to “design.md”">​</a></h1><p><a href="https://ui.docs.xihanfun.com/design.md" target="_blank" rel="noreferrer"><code>design.md</code></a> 是给 AI 设计与编码工具读的设计语言文件，描述 XiHan.UI 缺省主题（浅色 · 舒适密度 · 基础对比度）的颜色、排版、间距、圆角、组件样式令牌与视觉规则，帮助工具生成符合 XiHan.UI 视觉体系的界面。</p><h2 id="格式" tabindex="-1">格式 <a class="header-anchor" href="#格式" aria-label="Permalink to “格式”">​</a></h2><p>文件遵循 <a href="https://github.com/google-labs-code/design.md" target="_blank" rel="noreferrer">google-labs-code/design.md</a> 规范，分两部分：</p><ul><li><strong>YAML 头</strong>：机读令牌，包括 <code>colors</code>、<code>typography</code>、<code>rounded</code>、<code>spacing</code> 与 <code>components</code>。取值在构建时从 <code>@xihan-ui/tokens</code> 的 <code>tokens.json</code> 展开，不手抄，令牌改了它跟着改；组件条目引用前面的令牌，如 <code>{colors.primary}</code>、<code>{rounded.control}</code>。</li><li><strong>正文</strong>：按 Overview、Colors、Typography、Layout、Elevation &amp; Depth、Shapes、Components、Do&#39;s and Don&#39;ts 的顺序说明视觉规则，最后一节 Customization 说明怎样改品牌色、视觉环境与令牌。</li></ul><p>正文是 <a href="/design/">设计</a> 一册的浓缩：中性克制、边界由描边承担、4px 网格、圆角只有 control / surface / overlay 三个角色、阴影只表达抬升、组件按六个家族取样式。</p><h2 id="使用方式" tabindex="-1">使用方式 <a class="header-anchor" href="#使用方式" aria-label="Permalink to “使用方式”">​</a></h2><p><strong>在线读取</strong>：让工具直接访问文件地址。</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>阅读 https://ui.docs.xihanfun.com/design.md，按其中的 XiHan.UI 视觉语言生成界面。</span></span></code></pre></div><p><strong>用 CLI 取</strong>：工具不能访问网址时，用 <a href="./cli">CLI</a> 输出同一份内容，版本与 CLI 一致。</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -y</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @xihan-ui/cli</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> design.md</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> DESIGN.md</span></span></code></pre></div><p><strong>经 MCP 取</strong>：接入 <a href="./mcp">MCP Server</a> 后调用 <code>xihan_ui_design_md</code> 工具。</p><h2 id="适用场景" tabindex="-1">适用场景 <a class="header-anchor" href="#适用场景" aria-label="Permalink to “适用场景”">​</a></h2><ul><li>让 AI 生成整页界面或页面草图时，作为视觉约束；</li><li>让设计类工具理解 XiHan.UI 的缺省主题与组件形态；</li><li>判断「这里该用什么颜色、圆角、阴影」这类视觉取舍。</li></ul><p>design.md 只描述缺省主题。项目改过品牌色或令牌时，以项目里的令牌为准：用 <code>xihan-ui token &lt;关键字&gt;</code> 查令牌名，写代码时引用令牌而不是 design.md 里的取值。</p><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to “相关”">​</a></h2><ul><li><a href="/design/">设计体系</a> · <a href="./../guide/theme">设计令牌与主题</a> · <a href="/design/theme-designer">主题设计器</a></li><li><a href="./agents">For Agents</a> · <a href="./llms">LLMs.txt</a></li></ul>`,17)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};